// The sidebar agent: one question in, two answers out.
//
//   1. Instant — the catalog's own search ranks the modules that match, so the
//      visitor has something to click within a few hundred ms.
//   2. Grounded — the docs module's `docs_ask` (RAG over the protocol docs,
//      generated by a small resident LFM) writes a plain answer and names the
//      pages it read. It is slow (~30-70s on this box) and queues behind other
//      askers, so the UI streams it in after the module matches.
//
// Both are public reads. Nothing here touches the wallet.

import { api, type ScoredModule } from "./api";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
/** next.config proxies this to the docs module's MCP server. */
export const DOCS_MCP = `${BASE}/_api/docs/mcp`;

export type AgentAnswer = {
  ok: boolean;
  answer: string;
  sources: string[];
  model?: string;
};

export type ChatMsg =
  | { id: string; role: "user"; text: string; at: number }
  | {
      id: string;
      role: "agent";
      at: number;
      mods?: ScoredModule[];
      answer?: string;
      sources?: string[];
      model?: string;
      pending?: boolean;
      error?: string;
    };

export async function findModules(q: string, limit = 4): Promise<ScoredModule[]> {
  const r = await api.search(q, limit);
  return r.results.slice(0, limit);
}

export async function askDocs(question: string, signal?: AbortSignal): Promise<AgentAnswer> {
  const res = await fetch(DOCS_MCP, {
    method: "POST",
    headers: { "content-type": "application/json" },
    signal,
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: Date.now(),
      method: "tools/call",
      params: { name: "docs_ask", arguments: { question } },
    }),
  });
  if (!res.ok) throw new Error(`agent unreachable (${res.status})`);
  const body = await res.json();
  if (body.error) throw new Error(body.error.message || "agent error");
  const out = body.result?.structuredContent as AgentAnswer | undefined;
  if (out) return out;
  const text = body.result?.content?.[0]?.text;
  return text ? (JSON.parse(text) as AgentAnswer) : { ok: false, answer: "", sources: [] };
}

const CHAT_KEY = "mod.web.agent.chat";

export function loadChat(): ChatMsg[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = JSON.parse(localStorage.getItem(CHAT_KEY) || "[]") as ChatMsg[];
    // A reload kills the in-flight ask; don't leave a spinner that never ends.
    return raw.map((m) =>
      m.role === "agent" && m.pending
        ? { ...m, pending: false, error: m.answer ? undefined : "interrupted — ask again" }
        : m,
    );
  } catch {
    return [];
  }
}

export function saveChat(msgs: ChatMsg[]) {
  try {
    localStorage.setItem(CHAT_KEY, JSON.stringify(msgs.slice(-40)));
  } catch {
    /* quota / private mode: the chat just doesn't persist */
  }
}
